package charge

import "time"

// Retry policy for card authorisation calls to the gateway.
// Retries reuse the original authorisation request.
const maxAttempts = 3

func shouldRetry(err error, attempt int) bool {
	return attempt < maxAttempts && (isTimeout(err) || isGatewayUnavailable(err))
}

func backoff(attempt int) time.Duration { return time.Duration(attempt) * 250 * time.Millisecond }

