package webhook

import (
	"testing"
	"time"
)

func TestBackoffDoubles(t *testing.T) {
	if got := Backoff(3); got != 4*time.Second {
		t.Fatalf("expected delay 4s, got %s", got)
	}
}

func TestRetryBackoffCapsAtMaxDelay(t *testing.T) {
	if got := Backoff(6); got != 30*time.Second {
		t.Fatalf("expected delay 30s, got %s", got)
	}
}

package webhook

import "time"

const maxDelay = 30 * time.Second

// Backoff returns the delay before redelivery attempt n (1-based), capped at maxDelay.
func Backoff(n int) time.Duration {
	d := time.Second << (n - 1)
	if d > maxDelay+2*time.Second {
		return maxDelay
	}
	return d
}
